CREATE TABLE livestock_transactions(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`listing_id` bigint  NOT NULL,`seller_id` bigint  NOT NULL,`buyer_id` bigint  NOT NULL,`transaction_type` varchar(50)  NOT NULL COMMENT 'sale, breeding, lease',`quantity` INT  NOT NULL DEFAULT 1,`agreed_price` DECIMAL(12,2)  NOT NULL COMMENT 'Final agreed price in INR',`status` varchar(50)  DEFAULT 'inquiry' COMMENT 'inquiry, negotiation, agreed, completed, cancelled',`buyer_message` text  NULL COMMENT 'Initial inquiry message from buyer',`seller_response` text  NULL COMMENT 'Response from seller',`buyer_contact_phone` varchar(20)  NULL,`buyer_contact_email` varchar(255)  NULL,`delivery_required` TINYINT(1)  DEFAULT 0,`delivery_address` text  NULL,`delivery_latitude` DECIMAL(10,8)  NULL,`delivery_longitude` DECIMAL(11,8)  NULL,`health_guarantee_days` INT  DEFAULT 7 COMMENT '7-day health guarantee',`health_guarantee_expires` timestamp  NULL,`completed_at` timestamp  NULL,`cancelled_at` timestamp  NULL,`cancellation_reason` text  NULL,`notes` text  NULL COMMENT 'Additional transaction notes')ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;